# frozen_string_literal: true

require_relative 'plan'

module NapiGen
  # Formats a Plan as src/gen/ta_napi.{c,h}. Every decision is already in the
  # plan; this only writes C.
  class Emit
    # The banner names the inputs and their digests, so any edit to either
    # makes the checked-in output stale (ADR 0013).
    def self.banner(inputs)
      digests = inputs.map { |label, digest| " *   #{label} sha256:#{digest}" }
      <<~C
        /*
         * GENERATED by `mise run bindings` (tinyactors-napi/mise/lib/napi) from:
        #{digests.join("\n")}
         * Do not edit: change the API description or the policy and regenerate
         * (ADR 0013).
         */
      C
    end

    RUNTIME_KINDS = %i[int bigint u64n bool runtime override adapter].freeze

    def initialize(plan, inputs)
      @banner = self.class.banner(inputs)
      @plan = plan
      @api = plan.api
      @handles_used = {}
      collect_handles
    end

    def header
      <<~C
        #{@banner.chomp}
        #pragma once

        #include <node_api.h>

        /*
         * Defines exports.core: one function per bound core function, named
         * without the ta_ prefix. The module is internal (ADR 0013 point 7).
         */
        napi_status tna_gen_define(napi_env env, napi_value exports);
      C
    end

    def source
      out = []
      out << @banner
      out << <<~C
        #include "gen/ta_napi.h"

        #include <string.h>

        #include "hooks.h"
        #include "runtime.h"
        #include "system.h"
        #include "tinyactors.h"
      C
      out << result_codes
      out << handle_kinds
      out << prototypes
      @plan.decoders.each_value { |codec| out << decoder(codec) unless RUNTIME_KINDS.include?(codec.kind) }
      @plan.encoders.each_value { |codec| out << encoder(codec) unless RUNTIME_KINDS.include?(codec.kind) }
      @plan.list_decoders.each { |id, (codec, terminator)| out << list_decoder(id, codec, terminator) }
      @plan.array_decoders.each { |id, (codec, _count)| out << array_decoder(id, codec) }
      @plan.array_encoders.each { |id, (codec, _count)| out << array_encoder(id, codec) }
      @plan.list_encoders.each { |id, (codec, terminator)| out << list_encoder(id, codec, terminator) }
      @plan.functions.each { |function| out << function_source(function) }
      out << define
      "#{out.map { |part| part.end_with?("\n") ? part : "#{part}\n" }.join("\n").rstrip}\n"
    end

    private

    # ------------------------------------------------------------------
    # Tables

    def result_codes
      cases = @plan.result_codes.map { |constant, code| "    case #{constant}: return #{code.to_json};" }
      <<~C
        /* The TinyactorsErrorCode of each core result (ADR 0008). */
        const char *tna_result_code(ta_result result) {
            switch (result) {
        #{cases.join("\n")}
            default: return "invalid";
            }
        }
      C
    end

    def collect_handles
      @plan.functions.each do |function|
        function.args.each { |arg| @handles_used[arg.field.handle] = true if arg.field.form == :handle }
        function.outputs.each { |output| @handles_used[output.handle] = true if output.form == :handle }
      end
      @plan.decoders.each_value do |codec|
        next unless codec.kind == :struct

        each_field(@plan.record(codec.name)) { |field| @handles_used[field.handle] = true if field.form == :handle }
      end
    end

    def each_field(record, &block)
      fields = record.fields + (record.tagged&.members&.map(&:field) || [])
      fields.compact.each do |field|
        block.call(field)
        field.fields&.compact&.each(&block)
      end
    end

    def handle_kinds
      @handles_used.keys.sort.map do |name|
        handle = @plan.handles.fetch(name)
        release = handle[:release] or raise Error, "handle #{name} has no destroy function"
        <<~C
          static void tna_release_#{name}(void *pointer) {
              #{release}(pointer);
          }

          static const tna_handle_kind tna_handle_#{name} = { #{name.to_json}, tna_release_#{name}, #{handle[:reclaimed]} };
        C
      end.join("\n")
    end

    def prototypes
      lines = ['/* Codecs generated below. */']
      @plan.decoders.each_value do |codec|
        next if RUNTIME_KINDS.include?(codec.kind)

        lines << "static bool tna_dec_#{codec.id}(tna_call *c, napi_value v, #{codec.ctype} *out);"
      end
      @plan.encoders.each_value do |codec|
        next if RUNTIME_KINDS.include?(codec.kind)

        lines << "static napi_value tna_enc_#{codec.id}(tna_call *c, const #{codec.ctype} *in);"
      end
      @plan.list_decoders.each_key { |id| lines << "static bool tna_dec_list_#{id}(tna_call *c, napi_value v, tna_items *out);" }
      @plan.array_decoders.each_key { |id| lines << "static bool tna_dec_array_#{id}(tna_call *c, napi_value v, tna_items *out);" }
      @plan.array_encoders.each do |id, (codec, _)|
        lines << "static napi_value tna_enc_array_#{id}(tna_call *c, const #{codec.ctype} *items, uint32_t count);"
      end
      @plan.list_encoders.each do |id, (codec, _)|
        lines << "static napi_value tna_enc_list_#{id}(tna_call *c, const #{codec.ctype} *items);"
      end
      "#{lines.join("\n")}\n"
    end

    # ------------------------------------------------------------------
    # Enums

    def enum_constants(name)
      seen = {}
      @api.type(name)['constants'].reject { |constant| seen[constant['value']].tap { seen[constant['value']] = true } }
    end

    def decoder(codec)
      codec.kind == :enum ? enum_decoder(codec.name) : struct_decoder(@plan.record(codec.name))
    end

    def encoder(codec)
      codec.kind == :enum ? enum_encoder(codec.name) : struct_encoder(@plan.record(codec.name))
    end

    def enum_decoder(name)
      constants = @api.type(name)['constants']
      checks = constants.map do |constant|
        "    if (strcmp(symbol.text, #{constant['symbol'].to_json}) == 0) {\n" \
          "        *out = #{constant['name']};\n        return true;\n    }"
      end
      expected = "one of #{constants.map { |constant| constant['symbol'].to_json }.join(', ')}"
      <<~C
        static bool tna_dec_#{name}(tna_call *c, napi_value v, #{name} *out) {
            tna_symbol symbol;
            if (!tna_read_symbol(c, v, &symbol)) {
                return false;
            }
        #{checks.join("\n")}
            return tna_invalid(c, #{expected.to_json});
        }
      C
    end

    def enum_encoder(name)
      cases = enum_constants(name).map { |constant| "    case #{constant['name']}: return tna_string(c, #{constant['symbol'].to_json});" }
      <<~C
        static napi_value tna_enc_#{name}(tna_call *c, const #{name} *in) {
            switch (*in) {
        #{cases.join("\n")}
            default: return tna_number(c, (double)*in);
            }
        }
      C
    end

    # ------------------------------------------------------------------
    # Struct decoders

    def struct_decoder(record)
      body = []
      body << '    if (tna_absent(c, v)) {' << '        return true;' << '    }' if record.zero_is_absent
      body << '    if (!tna_expect_object(c, v)) {' << '        return false;' << '    }'
      decode_fields(body, record.fields, 'v', 'out->', 1)
      decode_tagged(body, record, 'v', 'out->', 1) if record.tagged
      body << '    return true;'
      <<~C
        static bool tna_dec_#{record.name}(tna_call *c, napi_value v, #{record.name} *out) {
        #{body.join("\n")}
        }
      C
    end

    def pad(depth) = '    ' * depth

    def decode_fields(body, fields, object, prefix, depth)
      fields.compact.each { |field| decode_member(body, field, field.name, object, "#{prefix}#{field.name}", depth) }
    end

    # Decodes member `key` of JavaScript `object` into C lvalue `target`.
    def decode_member(body, field, key, object, target, depth)
      i = pad(depth)
      case field.form
      when :output, :derived then return
      when :inject
        body << "#{i}if (!tna_inject_#{field.codec.id}(c, &#{target})) {" << "#{i}    return false;" << "#{i}}"
        return
      when :arena
        body << "#{i}#{target} = tna_call_arena(c);" << "#{i}if (#{target} == NULL) {" << "#{i}    return false;" << "#{i}}"
        return
      end
      value = "f#{depth}"
      body << "#{i}if (!tna_member(c, #{object}, #{key.to_json})) {" << "#{i}    return false;" << "#{i}}"
      body << "#{i}{"
      body << "#{i}    napi_value #{value} = tna_member_value(c);"
      decode_value(body, field, value, target, depth + 1, required: false)
      body << "#{i}}"
      body << "#{i}tna_pop(c);"
    end

    # Decodes JavaScript `value` (already read) into `target`.
    def decode_value(body, field, value, target, depth, required:, fail: 'return false;')
      i = pad(depth)
      fail_line = "#{i}    #{fail}"
      case field.form
      when :value
        body << "#{i}if (!tna_absent(c, #{value}) && !tna_dec_#{field.codec.id}(c, #{value}, &#{target})) {" << fail_line << "#{i}}"
      when :pointer
        ctype = field.codec.ctype
        absent(body, value, i, required || !field.optional, fail)
        body << "#{i}if (!tna_absent(c, #{value})) {"
        body << "#{i}    #{ctype} *p = tna_call_alloc(c, sizeof *p, _Alignof(#{ctype}));"
        body << "#{i}    if (p == NULL || !tna_dec_#{field.codec.id}(c, #{value}, p)) {" << "#{i}        #{fail}" << "#{i}    }"
        body << "#{i}    #{target} = p;"
        body << "#{i}}"
      when :handle
        absent(body, value, i, required || !field.optional, fail)
        body << "#{i}if (!tna_absent(c, #{value})) {"
        body << "#{i}    tna_handle_ref h = { &tna_handle_#{field.handle}, NULL };"
        body << "#{i}    if (!tna_handle_unwrap(c, #{value}, &h)) {" << "#{i}        #{fail}" << "#{i}    }"
        body << "#{i}    #{target} = h.pointer;"
        body << "#{i}}"
      when :list, :array
        absent(body, value, i, required || !field.optional, fail)
        helper = field.form == :list ? 'list' : 'array'
        body << "#{i}if (!tna_absent(c, #{value})) {"
        body << "#{i}    tna_items items = { NULL, 0 };"
        body << "#{i}    if (!tna_dec_#{helper}_#{field.codec.id}(c, #{value}, &items)) {" << "#{i}        #{fail}" << "#{i}    }"
        body << "#{i}    #{target} = items.items;"
        if field.form == :array
          count = target.sub(/[^.>]+\z/, field.count)
          body << "#{i}    #{count} = (#{field.element_ctype})items.count;"
        end
        body << "#{i}}"
      when :record
        body << "#{i}if (!tna_absent(c, #{value})) {"
        body << "#{i}    if (!tna_expect_object(c, #{value})) {" << "#{i}        return false;" << "#{i}    }"
        decode_fields(body, field.fields, value, "#{target}.", depth + 1)
        body << "#{i}}"
      else
        raise Error, "cannot decode a #{field.form} member (#{target})"
      end
    end

    def absent(body, value, indent, required, fail = 'return false;')
      return unless required

      body << "#{indent}if (tna_absent(c, #{value})) {" << "#{indent}    tna_invalid(c, \"a value\");" << "#{indent}    #{fail}" << "#{indent}}"
    end

    def decode_tagged(body, record, object, prefix, depth)
      tagged = record.tagged
      i = pad(depth)
      body << "#{i}if (!tna_member(c, #{object}, #{tagged.tag.to_json})) {" << "#{i}    return false;" << "#{i}}"
      body << "#{i}if (!tna_dec_#{tagged.enum}(c, tna_member_value(c), &#{prefix}#{tagged.tag})) {" << "#{i}    return false;" << "#{i}}"
      body << "#{i}tna_pop(c);"
      body << "#{i}switch (#{prefix}#{tagged.tag}) {"
      tagged.members.each do |member|
        next unless member.field

        body << "#{i}case #{member.constant}:"
        decode_member(body, member.field, member.field.name, object, "#{prefix}#{tagged.union}.#{member.field.name}", depth + 1)
        body << "#{i}    break;"
      end
      body << "#{i}default:" << "#{i}    break;" << "#{i}}"
    end

    # ------------------------------------------------------------------
    # Struct encoders

    def struct_encoder(record)
      body = []
      if record.zero_is_absent && record.tagged
        body << "    if (in->#{record.tagged.tag} == 0) {" << '        return tna_undefined(c);' << '    }'
      end
      body << '    napi_value o = tna_object(c);'
      body << '    if (o == NULL) {' << '        return NULL;' << '    }'
      encode_fields(body, record.fields, 'o', 'in->', 1)
      encode_tagged(body, record, 'o', 'in->', 1) if record.tagged
      body << '    return o;'
      <<~C
        static napi_value tna_enc_#{record.name}(tna_call *c, const #{record.name} *in) {
        #{body.join("\n")}
        }
      C
    end

    def encode_fields(body, fields, object, prefix, depth)
      fields.compact.each { |field| encode_member(body, field, field.name, object, "#{prefix}#{field.name}", depth) }
    end

    def encode_member(body, field, key, object, source, depth)
      i = pad(depth)
      return if %i[output derived arena].include?(field.form)

      value = "x#{depth}"
      body << "#{i}{"
      if field.form == :record
        body << "#{i}    napi_value #{value} = tna_object(c);"
        body << "#{i}    if (#{value} == NULL) {" << "#{i}        return NULL;" << "#{i}    }"
        encode_fields(body, field.fields, value, "#{source}.", depth + 1)
      else
        body << "#{i}    napi_value #{value} = #{encode_expression(field, source)};"
      end
      body << "#{i}    if (#{value} == NULL || !tna_ok(c, napi_set_named_property(c->env, #{object}, #{key.to_json}, #{value}))) {"
      body << "#{i}        return NULL;" << "#{i}    }"
      body << "#{i}}"
    end

    def encode_expression(field, source)
      id = field.codec&.id
      case field.form
      when :value, :inject then "tna_enc_#{id}(c, &#{source})"
      when :pointer then "#{source} == NULL ? tna_undefined(c) : tna_enc_#{id}(c, #{source})"
      when :list then "#{source} == NULL ? tna_undefined(c) : tna_enc_list_#{id}(c, #{source})"
      when :array
        count = source.sub(/[^.>]+\z/, field.count)
        "tna_enc_array_#{id}(c, #{source}, (uint32_t)#{count})"
      else raise Error, "cannot encode a #{field.form} member (#{source})"
      end
    end

    def encode_tagged(body, record, object, prefix, depth)
      tagged = record.tagged
      i = pad(depth)
      body << "#{i}{"
      body << "#{i}    napi_value t = tna_enc_#{tagged.enum}(c, &#{prefix}#{tagged.tag});"
      body << "#{i}    if (t == NULL || !tna_ok(c, napi_set_named_property(c->env, #{object}, #{tagged.tag.to_json}, t))) {"
      body << "#{i}        return NULL;" << "#{i}    }"
      body << "#{i}}"
      body << "#{i}switch (#{prefix}#{tagged.tag}) {"
      tagged.members.each do |member|
        next unless member.field

        body << "#{i}case #{member.constant}:"
        encode_member(body, member.field, member.field.name, object, "#{prefix}#{tagged.union}.#{member.field.name}", depth + 1)
        body << "#{i}    break;"
      end
      body << "#{i}default:" << "#{i}    break;" << "#{i}}"
    end

    # ------------------------------------------------------------------
    # Lists

    def list_decoder(id, codec, terminator)
      ctype = codec.ctype
      <<~C
        static bool tna_dec_list_#{id}(tna_call *c, napi_value v, tna_items *out) {
            uint32_t length = 0;
            if (!tna_array_length(c, v, &length)) {
                return false;
            }
            #{ctype} *items = tna_call_alloc(c, sizeof(#{ctype}) * ((size_t)length + 1u), _Alignof(#{ctype}));
            if (items == NULL) {
                return false;
            }
            for (uint32_t index = 0; index < length; index += 1u) {
                napi_value element = NULL;
                tna_push_index(c, index);
                if (!tna_ok(c, napi_get_element(c->env, v, index, &element)) || !tna_dec_#{id}(c, element, &items[index])) {
                    return false;
                }
                const #{ctype} *item = &items[index];
                if (#{terminator}) {
                    return tna_invalid(c, "an element that does not end the list");
                }
                tna_pop(c);
            }
            out->items = items;
            out->count = length;
            return true;
        }
      C
    end

    def array_decoder(id, codec)
      ctype = codec.ctype
      <<~C
        static bool tna_dec_array_#{id}(tna_call *c, napi_value v, tna_items *out) {
            uint32_t length = 0;
            if (!tna_array_length(c, v, &length)) {
                return false;
            }
            #{ctype} *items = tna_call_alloc(c, sizeof(#{ctype}) * (size_t)length, _Alignof(#{ctype}));
            if (items == NULL) {
                return false;
            }
            for (uint32_t index = 0; index < length; index += 1u) {
                napi_value element = NULL;
                tna_push_index(c, index);
                if (!tna_ok(c, napi_get_element(c->env, v, index, &element)) || !tna_dec_#{id}(c, element, &items[index])) {
                    return false;
                }
                tna_pop(c);
            }
            out->items = items;
            out->count = length;
            return true;
        }
      C
    end

    def array_encoder(id, codec)
      ctype = codec.ctype
      <<~C
        static napi_value tna_enc_array_#{id}(tna_call *c, const #{ctype} *items, uint32_t count) {
            napi_value array = tna_new_array(c, items == NULL ? 0 : count);
            if (array == NULL) {
                return NULL;
            }
            for (uint32_t index = 0; items != NULL && index < count; index += 1u) {
                napi_value element = tna_enc_#{id}(c, &items[index]);
                if (element == NULL || !tna_ok(c, napi_set_element(c->env, array, index, element))) {
                    return NULL;
                }
            }
            return array;
        }
      C
    end

    def list_encoder(id, codec, terminator)
      ctype = codec.ctype
      <<~C
        static napi_value tna_enc_list_#{id}(tna_call *c, const #{ctype} *items) {
            uint32_t count = 0;
            for (;;) {
                const #{ctype} *item = &items[count];
                if (#{terminator}) {
                    break;
                }
                count += 1u;
            }
            return tna_enc_array_#{id}(c, items, count);
        }
      C
    end

    # ------------------------------------------------------------------
    # Functions

    def argv_layout(function)
      index = function.receiver ? 1 : 0
      function.args.map do |arg|
        taken = if %i[inject arena].include?(arg.field.form) then 0
                elsif arg.pair then 2
                else 1
                end
        position = index
        index += taken
        [arg, position, taken]
      end.then { |layout| [layout, index] }
    end

    def function_source(function)
      layout, argc = argv_layout(function)
      body = []
      body << '    tna_call call;'
      body << '    tna_call *c = &call;'
      body << "    napi_value argv[#{[argc, 1].max}];"
      body << "    size_t argc = #{[argc, 1].max};"
      body << "    tna_call_begin(c, env, \"core.#{function.js}\");"
      body << '    if (!tna_ok(c, napi_get_cb_info(env, info, &argc, argv, NULL, NULL))) {'
      body << '        goto fail;' << '    }'
      if function.receiver
        body << '    if (!tna_call_receiver(c, argv[0])) {' << '        goto fail;' << '    }'
      end
      if function.params_struct
        body << "    #{function.params_struct} params;"
        body << '    memset(&params, 0, sizeof params);'
      end
      function.args.each do |arg|
        next unless arg.decl

        body << "    #{arg.decl};"
        body << "    memset(&#{arg.target}, 0, sizeof #{arg.target});"
      end
      declare_outputs(body, function)
      layout.each { |arg, position, _| decode_arg(body, function, arg, position) }
      function.outputs.each { |output| body << "    #{output.bind}" if output.bind.is_a?(String) }
      if function.buffer
        buffer_call(body, function)
      else
        plain_call(body, function, layout)
      end
      body << 'fail:'
      body << '    return tna_call_end(c, NULL);'
      <<~C
        /* #{function.name}#{function.category == :hooked ? " (hooked: #{function.reason[:reason]})" : ''} */
        static napi_value tna_fn_#{function.js}(napi_env env, napi_callback_info info) {
        #{body.join("\n")}
        }
      C
    end

    def declare_outputs(body, function)
      function.outputs.each do |output|
        case output.form
        when :value
          body << "    #{output.ctype} #{output.storage};"
          body << "    memset(&#{output.storage}, 0, sizeof #{output.storage});"
        when :handle, :view
          body << "    #{output.ctype}#{output.storage} = NULL;"
        end
      end
    end

    def decode_arg(body, _function, arg, position)
      field = arg.field
      label = arg.target.sub(/\A(a_|params\.)/, '')
      case field.form
      when :inject
        body << "    if (!tna_inject_#{field.codec.id}(c, &#{arg.target})) {" << '        goto fail;' << '    }'
        return
      when :arena
        body << "    #{arg.target} = tna_call_arena(c);" << "    if (#{arg.target} == NULL) {" << '        goto fail;' << '    }'
        return
      end
      body << "    tna_push(c, #{label.to_json});"
      if arg.pair
        body << "    if (!tna_dec_actor_pair(c, &argv[#{position}], &#{arg.target})) {" << '        goto fail;' << '    }'
      else
        if field.form == :value && arg.required
          body << "    if (tna_absent(c, argv[#{position}])) {" << '        tna_invalid(c, "a value");' << '        goto fail;' << '    }'
        end
        decode_value(body, field, "argv[#{position}]", arg.target, 1, required: arg.required, fail: 'goto fail;')
      end
      body << '    tna_pop(c);'
    end

    def call_expression(function)
      "#{function.name}(#{function.call.join(', ')})"
    end

    def core_call(body, function, assign)
      body << '    tna_core_enter(c);'
      body << "    #{assign}#{call_expression(function)};"
      body << '    tna_core_leave(c);'
    end

    def plain_call(body, function, layout)
      result = function.result
      case result[:kind]
      when :status
        body << '    ta_result r = TA_OK;'
        core_call(body, function, 'r = ')
      when :void
        body << '    ta_result r = TA_OK;'
        core_call(body, function, '')
      when :value
        body << '    ta_result r = TA_OK;'
        body << "    #{result[:ctype]} rv;"
        core_call(body, function, 'rv = ')
      end
      body << '    (void)r;'
      retire(body, function, layout)
      if result[:kind] == :status
        body << '    if (r != TA_OK) {'
        failure_detail(body, function)
        releases(body, function)
        body << '        return tna_call_end(c, tna_call_fail(c, r, detail));'
        body << '    }'
      end
      if function.hook
        body << "    r = #{function.hook[:name]}(tna_call_system(c), #{function.hook[:actor]});"
        body << '    if (r != TA_OK) {'
        body << '        return tna_call_end(c, tna_call_fail(c, r, NULL));'
        body << '    }'
      end
      encode_outputs(body, function)
      releases(body, function, indent: 1)
      body << '    if (result == NULL) {' << '        goto fail;' << '    }'
      body << '    return tna_call_end(c, result);'
    end

    def retire(body, function, layout)
      function.retire.each do |entry|
        position = layout[entry[:index]][1]
        condition = entry[:on] ? "r == #{entry[:on]}" : nil
        line = "tna_handle_retire(c, argv[#{position}]);"
        body << (condition ? "    if (#{condition}) {\n        #{line}\n    }" : "    #{line}")
      end
    end

    # Outputs valid on a failure become the error's `detail`.
    def failure_detail(body, function)
      failing = function.outputs.select { |output| %i[value view].include?(output.form) && output.valid != 'r == TA_OK' }
      body << '        napi_value detail = NULL;'
      return if failing.empty?

      body << '        detail = tna_object(c);'
      failing.each do |output|
        condition = [output.valid, output.form == :view ? "#{output.storage} != NULL" : nil].compact.join(' && ')
        condition = 'true' if condition.empty?
        expression = output.form == :view ? "tna_enc_#{output.codec.id}(c, #{output.storage})" : "tna_enc_#{output.codec.id}(c, &#{output.storage})"
        body << "        if (detail != NULL && (#{condition})) {"
        body << "            napi_value x = #{expression};"
        body << "            if (x == NULL || !tna_ok(c, napi_set_named_property(env, detail, #{output.key.to_json}, x))) {"
        body << '                detail = NULL;' << '            }'
        body << '        }'
      end
    end

    def releases(body, function, indent: 2)
      i = pad(indent)
      function.outputs.each do |output|
        next if output.releases.nil? || output.releases.empty?

        condition = output.valid || 'true'
        body << "#{i}if (#{condition}) {"
        output.releases.each { |line| body << "#{i}    #{line}" }
        body << "#{i}}"
      end
    end

    def output_expression(output)
      condition = output.valid
      expression = case output.form
                   when :value then "tna_enc_#{output.codec.id}(c, &#{output.storage})"
                   when :view
                     condition = [condition, "#{output.storage} != NULL"].compact.join(' && ')
                     "tna_enc_#{output.codec.id}(c, #{output.storage})"
                   when :handle
                     condition = [condition, "#{output.storage} != NULL"].compact.join(' && ')
                     "tna_handle_wrap(c, &tna_handle_#{output.handle}, (void *)#{output.storage})"
                   end
      condition.nil? || condition.empty? ? expression : "(#{condition}) ? #{expression} : tna_undefined(c)"
    end

    def encode_outputs(body, function)
      outputs = function.outputs
      if outputs.empty?
        body << (function.result[:kind] == :value ? "    napi_value result = tna_enc_#{function.result[:codec].id}(c, &rv);" : '    napi_value result = tna_undefined(c);')
      elsif outputs.size == 1
        body << "    napi_value result = #{output_expression(outputs.first)};"
      else
        body << '    napi_value result = tna_object(c);'
        outputs.each do |output|
          body << '    if (result != NULL) {'
          body << "        napi_value x = #{output_expression(output)};"
          body << "        if (x == NULL || !tna_ok(c, napi_set_named_property(env, result, #{output.key.to_json}, x))) {"
          body << '            result = NULL;' << '        }'
          body << '    }'
        end
      end
    end

    # A caller buffer: ask for the size, then fill a buffer from the call arena.
    def buffer_call(body, function)
      output = function.buffer
      bind = output.bind
      ctype = output.ctype
      body << '    uint32_t needed = 0;'
      body << "    #{bind[:needed]} = &needed;"
      body << '    ta_result r = TA_OK;'
      core_call(body, function, 'r = ')
      body << '    if ((r == TA_OK || r == TA_ERR_NOMEM) && needed > 0) {'
      body << "        #{output.storage} = tna_call_alloc(c, sizeof(#{ctype}) * (size_t)needed, _Alignof(#{ctype}));"
      body << "        if (#{output.storage} == NULL) {" << '            goto fail;' << '        }'
      body << "        #{bind[:capacity]} = needed;"
      body.concat(["    #{"    tna_core_enter(c);"}", "        r = #{call_expression(function)};", '        tna_core_leave(c);'])
      body << '    }'
      body << '    if (r != TA_OK) {' << '        return tna_call_end(c, tna_call_fail(c, r, NULL));' << '    }'
      if bind[:text]
        body << "    napi_value result = tna_enc_text(c, #{output.storage}, #{bind[:capacity]});"
      else
        count = "(needed < #{bind[:capacity]} ? needed : #{bind[:capacity]})"
        body << "    napi_value result = tna_enc_array_#{output.codec.id}(c, #{output.storage}, #{count});"
      end
      body << '    if (result == NULL) {' << '        goto fail;' << '    }'
      body << '    return tna_call_end(c, result);'
    end

    # ------------------------------------------------------------------
    # The module

    def define
      entries = @plan.functions.map do |function|
        "        { #{function.js.to_json}, NULL, tna_fn_#{function.js}, NULL, NULL, NULL, napi_default_jsproperty, NULL },"
      end
      <<~C
        napi_status tna_gen_define(napi_env env, napi_value exports) {
            static const napi_property_descriptor functions[] = {
        #{entries.join("\n")}
            };
            napi_value core = NULL;
            napi_status status = napi_create_object(env, &core);
            if (status == napi_ok) {
                status = napi_define_properties(env, core, sizeof functions / sizeof functions[0], functions);
            }
            if (status == napi_ok) {
                status = napi_set_named_property(env, exports, "core", core);
            }
            return status;
        }
      C
    end
  end
end
